  const translateSmart = value => {
    if(UI_TRANSLATIONS[value]) return UI_TRANSLATIONS[value];
    let out=value;
    Object.keys(UI_WORDS).sort((a,b)=>b.length-a.length).forEach(word=>{
      out=out.replace(new RegExp(`\\b${word.replace(/[.*+?^${}()|[\\]\\\\]/g,'\\\\$&')}\\b`,'gi'),UI_WORDS[word]);
    });
    return out;
  };
  function applyLanguage(){
    if(translating) return; translating=true;
    try{
      // The login screen is intentionally English-only. The selected language
      // is remembered and becomes effective only after successful login.
      const root=document.getElementById('dashboard-view');
      if(!root) return;
      const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);
      const nodes=[]; while(walker.nextNode()) nodes.push(walker.currentNode);
      nodes.forEach(node=>{
        const el=node.parentElement; if(!el||['SCRIPT','STYLE','SVG','OPTION'].includes(el.tagName)) return;
        if(!originalText.has(node)) originalText.set(node,node.nodeValue);
        const base=originalText.get(node); const trimmed=base.trim(); if(!trimmed) return;
        if(currentLanguage==='hi'){
          const translated=translateSmart(trimmed); if(translated!==trimmed){node.nodeValue=base.replace(trimmed,translated);}
        } else node.nodeValue=base;
      });
      const attrs=['placeholder','title','aria-label'];
      root.querySelectorAll('*').forEach(el=>{
        if(['SCRIPT','STYLE'].includes(el.tagName)) return;
        if(!originalAttrs.has(el)) originalAttrs.set(el,{});
        const saved=originalAttrs.get(el);
        attrs.forEach(a=>{if(el.hasAttribute(a)){if(saved[a]===undefined) saved[a]=el.getAttribute(a); const base=saved[a]; if(currentLanguage==='hi') el.setAttribute(a,translateSmart(base)); else el.setAttribute(a,base);}});
      });
      document.documentElement.lang=state.currentUser ? currentLanguage : 'en';
      document.querySelectorAll('.lang-switch').forEach(b=>b.classList.toggle('active',b.dataset.lang===currentLanguage));
    } finally { translating=false; }
  }
