  window.editLeave=idv=>{const x=state.data.leaves.find(v=>v.id===idv);if(!x)return;const from=promptText('From',x.from);if(from===null)return;const to=promptText('To',x.to);if(to===null)return;const reason=promptText('Reason',x.reason);if(reason===null)return;const status=promptText('Status Approved/Pending/Rejected',x.status);if(status===null)return;Object.assign(x,{from,to,reason,status});persist('leaves');addAudit('LEAVE_UPDATED',idv);renderSchedules();};
