  function getSlots(doctorId,date,type){
    const d=doctorById(doctorId);if(!d||d.status==='Inactive')return[];
    const dow=dayName(date), schedules=state.data.schedules.filter(s=>s.doctorId===doctorId&&s.day===dow&&s.type===type);
    const onLeave=state.data.leaves.some(l=>l.doctorId===doctorId&&l.status==='Approved'&&date>=l.from&&date<=l.to);if(onLeave)return[];
    const result=[];
    schedules.forEach(s=>{for(let t=minTime(s.start);t+30<=minTime(s.end);t+=30){const time=timeToStr(t);const booked=state.data.appointments.filter(a=>a.doctorId===doctorId&&a.date===date&&a.time===time&&a.status!=='Cancelled').length;if(booked<s.maxPatients)result.push({time,schedule:s,remaining:s.maxPatients-booked});}});return result;
  }
  function renderAppointments(){
    document.getElementById('view-appointments').innerHTML=pageHead('Appointments','Schedule-aware booking: only valid doctor slots are available',`<button class="btn btn-primary" onclick="openBookingModal()">Book Appointment</button>`)+`<div class="panel"><div class="filter-grid"><label>Doctor<select id="appt-doctor-filter"><option value="">All doctors</option>${state.data.doctors.map(d=>`<option value="${d.id}">${esc(d.name)}</option>`).join('')}</select></label><label>Date<input id="appt-date-filter" type="date" value="${today()}"></label><label>Type<select id="appt-type-filter"><option value="">All</option><option>OPD</option><option>ONLINE</option></select></label></div></div><div style="margin-top:15px">${tableWrap(['ID','Patient','Doctor','Specialty','Date','Time','Type','Status','Actions'],state.data.appointments.map(a=>`<tr><td>${a.id}</td><td>${esc(a.patientName)}</td><td>${esc(a.doctor)}</td><td>${esc(a.specialty)}</td><td>${a.date}</td><td>${a.time}</td><td>${tag(a.type,'info')}</td><td>${tag(a.status,a.status==='Confirmed'||a.status==='Completed'?'success':a.status==='Pending'?'warning':'danger')}</td><td>${actionBtns(`editAppointment('${a.id}')`,`deleteAppointment('${a.id}')`)}${a.status==='Pending'?`<button class="btn btn-sm btn-success" onclick="updateAppointment('${a.id}','Confirmed')">Confirm</button>`:''}</td></tr>`).join(''))}</div>`;lucide.createIcons();
  }
  window.openBookingModal=()=>{const p=state.data.patients[0];const d=state.data.doctors.find(x=>x.status==='Available')||state.data.doctors[0];if(!p||!d)return;showModal('Book Appointment',`<div class="form-grid"><label>Patient<select id="b-patient">${state.data.patients.map(x=>`<option value="${x.id}">${esc(x.name)} (${x.id})</option>`).join('')}</select></label><label>Doctor<select id="b-doctor">${state.data.doctors.filter(x=>x.status!=='Inactive').map(x=>`<option value="${x.id}">${esc(x.name)} — ${esc(x.specialty)}</option>`).join('')}</select></label><label>Date<input id="b-date" type="date" value="${today()}"></label><label>Type<select id="b-type"><option>OPD</option><option>ONLINE</option></select></label></div><div id="b-slots" class="slot-grid"></div><label style="display:block;margin-top:12px">Complaint<textarea id="b-complaint" rows="3"></textarea></label>`,`<button class="btn btn-outline" onclick="closeModal()">Cancel</button><button class="btn btn-primary" onclick="saveBooking()">Book Slot</button>`);const refresh=()=>{const slots=getSlots(document.getElementById('b-doctor').value,document.getElementById('b-date').value,document.getElementById('b-type').value);document.getElementById('b-slots').innerHTML=slots.map(s=>`<button type="button" class="slot" data-time="${s.time}">${s.time}<small>${s.remaining} left</small></button>`).join('')||'<div class="empty">No available slots for this doctor/date/type.</div>';document.querySelectorAll('#b-slots .slot').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('#b-slots .slot').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');}));};['b-doctor','b-date','b-type'].forEach(idv=>document.getElementById(idv).addEventListener('change',refresh));refresh();};
  window.saveBooking=()=>{const pid=document.getElementById('b-patient').value,did=document.getElementById('b-doctor').value,date=document.getElementById('b-date').value,type=document.getElementById('b-type').value;const slot=document.querySelector('#b-slots .slot.selected');if(!slot)return alert('Select an available time slot.');const p=patientById(pid),d=doctorById(did);const av=getSlots(did,date,type).find(x=>x.time===slot.dataset.time);if(!av)return alert('Selected slot is no longer available.');const x={id:makeId('APT'),patientId:pid,patientName:p.name,doctorId:did,doctor:d.name,department:d.department,specialty:d.specialty,date,time:slot.dataset.time,type,room:av.schedule.room,scheduleId:av.schedule.id,complaint:document.getElementById('b-complaint').value.trim(),status:'Pending',createdAt:nowISO()};state.data.appointments.push(x);persist('appointments');addAudit('APPOINTMENT_CREATED',x.id);closeModal();renderAppointments();};
  window.editAppointment=idv=>{const x=state.data.appointments.find(v=>v.id===idv);if(!x)return;const date=promptText('Date',x.date);if(date===null)return;const type=promptText('Type OPD/ONLINE',x.type);if(type===null)return;const slots=getSlots(x.doctorId,date,type);if(!slots.length)return alert('No slots available on selected date/type.');const time=promptText(`Available times: ${slots.map(s=>s.time).join(', ')}`,x.time);if(time===null)return;if(!slots.some(s=>s.time===time))return alert('Time is not an available slot.');Object.assign(x,{date,type,time,room:slots.find(s=>s.time===time).schedule.room,scheduleId:slots.find(s=>s.time===time).schedule.id});persist('appointments');addAudit('APPOINTMENT_UPDATED',idv);renderAppointments();};
  window.deleteAppointment=idv=>{if(!confirmDelete('appointment'))return;state.data.appointments=state.data.appointments.filter(x=>x.id!==idv);persist('appointments');addAudit('APPOINTMENT_DELETED',idv);renderAppointments();};
