  function renderPatients(){const rows=state.data.patients.map(p=>`<tr><td>${p.id}</td><td><strong>${esc(p.name)}</strong></td><td>${age(p.dob)}</td><td>${esc(p.gender)}</td><td>${tag(p.blood,'info')}</td><td>${esc(p.diagnosis)}</td><td>${actionBtns(`editPatient('${p.id}')`,`deletePatient('${p.id}')`)} <button class="btn btn-sm btn-outline" onclick="viewPatient('${p.id}')">View</button></td></tr>`).join('');document.getElementById('view-patients').innerHTML=pageHead('Patient Records','Digital health profiles and longitudinal clinical record',`<button class="btn btn-primary" onclick="addPatient()">Add Patient</button>`)+tableWrap(['ID','Name','Age','Gender','Blood','Diagnosis','Actions'],rows);lucide.createIcons();}
