  async function runAI(){
    const pid=document.getElementById('ai-patient')?.value||'';
    const symptoms=document.getElementById('ai-symptoms')?.value.trim()||'';
    if(!symptoms)return alert('Describe symptoms/problems first.');
    if(pid){const consent=state.data.consent.find(c=>c.patientId===pid && c.status==='Active'); if(!consent)return alert('AI analysis is disabled because active patient consent was not found. Enable consent first.');}
    const p=patientById(pid);
    const input={symptoms,bp:document.getElementById('ai-bp')?.value||'',hr:document.getElementById('ai-hr')?.value||'',temp:document.getElementById('ai-temp')?.value||'',spo2:document.getElementById('ai-spo2')?.value||'',labs:document.getElementById('ai-labs')?.value||''};
    const panel=document.getElementById('ai-result'); panel.innerHTML='<div class="ai-thinking"><strong>Analyzing...</strong><span>Preparing clinical decision-support summary.</span></div>';
    try{
      let result=AIService.analyzeLocally(input);
      if(state.data.settings.aiMode==='gemini'&&state.data.settings.geminiKey){result=await AIService.analyzeWithGemini(state.data.settings.geminiKey,state.data.settings.geminiModel,'You are clinical decision-support software. Never issue a final prescription. Return a clinician-review draft only. Emergency red flags must remain emergency.',input);}
      result.patientId=pid; result.patientName=p?.name||'Unregistered'; state.currentAI=result;
      if(result.triage==='EMERGENCY'){
        state.data.emergencies.push({id:makeId('EMG'),patientId:pid,patient:result.patientName,type:'AI red-flag escalation',priority:'Critical',status:'Active',createdAt:nowISO(),flags:clone(result.flags||[])});
        persist('emergencies'); addAudit('AI_EMERGENCY_ESCALATED',pid||'GENERAL');
        panel.innerHTML=`<div class="alert-card danger"><strong>Emergency Alert</strong><p>Red-flag information was detected. Do not route this case through routine telemedicine. Seek immediate in-person professional assessment.</p><ul>${(result.flags||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div><div class="ai-disclaimer">AI-generated draft — for clinical decision support only. Requires doctor approval.</div>`;
        return;
      }
      renderAiResult(result);
    }catch(e){panel.innerHTML=`<div class="alert-card danger">${esc(e.message)}</div>`;}
  }

  function renderAI(){const activeConsent=state.currentUser?.role==='Patient'?state.data.consent.find(c=>c.patientId===state.data.patients[0]?.id&&c.status==='Active'):true;document.getElementById('view-ai').innerHTML=pageHead('AI Clinical Assistant','Symptoms + vitals + reports → clinical summary → specialist routing → doctor-reviewed draft',`<span>${tag('Decision support only','warning')}</span>`)+`${activeConsent===false?`<div class="alert-card warning"><strong>AI analysis disabled</strong><p>Patient consent is required before AI-assisted analysis can run.</p></div>`:''}<div class="cards-2"><div class="panel"><h3>Clinical Input</h3><div class="form-grid"><label>Patient<select id="ai-patient"><option value="">Unregistered / General</option>${state.data.patients.map(p=>`<option value="${p.id}">${esc(p.name)} (${p.id})</option>`).join('')}</select></label><label>Blood Pressure<input id="ai-bp" placeholder="120/80"></label><label>Heart Rate<input id="ai-hr" type="number" placeholder="72"></label><label>Temperature<input id="ai-temp" type="number" step="0.1" placeholder="37.0"></label><label>SpO₂<input id="ai-spo2" type="number" placeholder="98"></label></div><label>Symptoms / Problem<textarea id="ai-symptoms" rows="6" placeholder="Describe the patient's problem, onset, severity, history..."></textarea></label><label>Reports / Lab Findings<textarea id="ai-labs" rows="4" placeholder="Paste report values or findings..."></textarea></label><button class="btn btn-primary btn-block" onclick="runAI()"><i data-lucide="sparkles"></i> Run AI Analysis</button></div><div class="panel" id="ai-result"><div class="empty">Run an assessment to see results.</div></div></div>`;lucide.createIcons();}
  function renderAiResult(r){const el=document.getElementById('ai-result');el.innerHTML=`<div class="ai-result-head"><div><span class="section-sub">Triage</span><div>${tag(r.triage,r.triage==='EMERGENCY'?'danger':r.triage==='URGENT'?'warning':'success')}</div></div><div>${tag(r.specialty,'info')}</div></div><div class="result-block"><h4>Clinical Summary</h4><p>${esc(r.summary)}</p></div><div class="result-block"><h4>Possible Clinical Considerations</h4>${(r.conditions||[]).map(c=>`<div class="condition"><div><strong>${esc(c.name)}</strong><span>${esc(c.confidence)}%</span></div><p>${esc(c.description)}</p><div class="meter"><span style="width:${Math.max(0,Math.min(100,Number(c.confidence)||0))}%"></span></div></div>`).join('')||'<div class="empty">None.</div>'}</div><div class="result-block"><h4>Risk Flags</h4>${(r.flags||[]).map(x=>`<div class="alert-card warning"><i data-lucide="alert-circle"></i><p>${esc(x)}</p></div>`).join('')||'<p class="muted">No additional flags.</p>'}</div><div class="result-block"><h4>Recommended Investigations</h4><ul>${(r.recommendedTests||[]).map(x=>`<li>${esc(x)}</li>`).join('')||'<li>No additional investigations suggested.</li>'}</ul></div><div class="result-block"><h4>Prescription Draft</h4><div class="alert-card info"><i data-lucide="shield-check"></i><div><strong>Clinician review required</strong><p>AI does not issue a final prescription.</p></div></div><div class="draft-box">${(r.prescriptionDraft||[]).map(x=>`<div class="list-row"><div><strong>${esc(x.item||x.medicine||'Draft item')}</strong><span>${esc(x.note||x.instructions||'Review clinically')}</span></div>${tag('DRAFT','warning')}</div>`).join('')||'<p class="muted">No medication draft returned by the engine.</p>'}</div></div><div class="result-actions"><button class="btn btn-outline" onclick="saveAIReport()">Save to Patient</button><button class="btn btn-primary" onclick="sendAIReview()">Send to Specialist Doctor</button></div><div class="ai-disclaimer"><i data-lucide="shield-alert"></i> AI output is decision support and not a definitive diagnosis or autonomous prescription.</div>`;lucide.createIcons();}
  window.saveAIReport=()=>{const r=state.currentAI;if(!r?.patientId)return alert('Select a registered patient.');const p=patientById(r.patientId);p.reports=p.reports||[];p.reports.push({id:makeId('REP'),date:nowISO(),triage:r.triage,summary:r.summary,recommendations:r.recommendations,conditions:r.conditions});persist('patients');addAudit('AI_REPORT_SAVED',p.id);alert('AI report saved to patient history.');};
  window.sendAIReview=()=>{const r=state.currentAI;if(!r)return;state.notifications.unshift({id:makeId('NOT'),type:'ai',title:'AI Clinical Review Request',patientId:r.patientId,patientName:r.patientName,specialty:r.specialty,triage:r.triage,result:clone(r),status:'Pending Doctor Review',createdAt:nowISO()});addAudit('AI_REVIEW_REQUESTED',r.patientId||'GENERAL');updateNotificationCount();alert(`Review request routed to ${r.specialty} queue.`);};

  function renderConsultations(){const rows=state.data.consultations.map(c=>`<tr><td>${c.id}</td><td>${esc(c.patient)}</td><td>${esc(c.specialty)}</td><td>${esc(c.doctor)}</td><td>${esc(c.mode)}</td><td>${tag(c.status,c.status==='Active'?'success':'')}</td><td>${actionBtns(`editConsultation('${c.id}')`,`deleteConsultation('${c.id}')`)}</td></tr>`).join('');document.getElementById('view-consultations').innerHTML=pageHead('Telemedicine & Second Opinion','Remote care and specialist access',`<button class="btn btn-primary" onclick="createConsultation()">Create Consultation</button>`)+`<div class="cards-3">${kpi('Active',state.data.consultations.filter(x=>x.status==='Active').length,'video','success')}${kpi('Completed',state.data.consultations.filter(x=>x.status==='Completed').length,'check-circle','primary')}${kpi('Total',state.data.consultations.length,'users','secondary')}</div>`+tableWrap(['ID','Patient','Specialty','Doctor','Mode','Status','Actions'],rows);lucide.createIcons();}
  window.createConsultation=()=>{const p=state.data.patients[0];const d=state.data.doctors.find(x=>x.onlineEligible&&x.status==='Available')||state.data.doctors[0];if(!p||!d)return;const x={id:makeId('CONS'),patient:p.name,patientId:p.id,specialty:d.specialty,doctor:d.name,mode:'Video',status:'Active',date:nowISO()};state.data.consultations.push(x);persist('consultations');addAudit('CONSULTATION_CREATED',x.id);renderConsultations();};
  window.editConsultation=idv=>{const x=state.data.consultations.find(v=>v.id===idv);if(!x)return;const doctor=promptText('Doctor',x.doctor);if(doctor===null)return;const mode=promptText('Mode Chat/Audio/Video',x.mode);if(mode===null)return;const status=promptText('Status Active/Completed/Cancelled',x.status);if(status===null)return;Object.assign(x,{doctor,mode,status});persist('consultations');addAudit('CONSULTATION_UPDATED',idv);renderConsultations();};
  window.deleteConsultation=idv=>{if(!confirmDelete('consultation'))return;state.data.consultations=state.data.consultations.filter(x=>x.id!==idv);persist('consultations');addAudit('CONSULTATION_DELETED',idv);renderConsultations();};

  function renderPrescriptions(){const canReview=['Doctor','HOD','Medical Director'].includes(state.currentUser?.role);const pending=state.notifications.filter(n=>n.type==='ai'&&n.status==='Pending Doctor Review');const existing=state.data.prescriptions.map(r=>`<tr><td>${r.id}</td><td>${esc(r.patient)}</td><td>${esc(r.specialty)}</td><td>${esc(r.doctor)}</td><td>${tag(r.decision||r.status,'success')}</td><td>${fmtDateTime(r.date)}</td><td>${actionBtns(`editPrescription('${r.id}')`,`deletePrescription('${r.id}')`)}</td></tr>`).join('');document.getElementById('view-prescriptions').innerHTML=pageHead('Prescription Review Center','AI drafts are routed to qualified doctors for approval, modification or rejection')+`<div class="panel"><div class="panel-header"><h3>Pending AI Reviews</h3><span>${tag(`${pending.filter(n=>n.status==='Pending Doctor Review').length} pending`,'warning')}</span></div>${pending.map(n=>`<div class="review-card"><div class="panel-header"><h3>${esc(n.patientName||'General')} · ${esc(n.specialty)}</h3>${tag(n.triage,n.triage==='EMERGENCY'?'danger':n.triage==='URGENT'?'warning':'success')}</div><div class="review-grid"><div><strong>AI Summary</strong><p>${esc(n.result?.summary||'')}</p><strong>Risk Flags</strong><ul>${(n.result?.flags||[]).map(x=>`<li>${esc(x)}</li>`).join('')||'<li>None</li>'}</ul><strong>Reports/Tests</strong><p>${esc((n.result?.recommendedTests||[]).join(', ')||'None')}</p></div><div><strong>Prescription Draft</strong>${(n.result?.prescriptionDraft||[]).map(x=>`<div class="list-row"><div><strong>${esc(x.item||x.medicine||'Draft item')}</strong><span>${esc(x.note||'Review clinically')}</span></div>${tag('DRAFT','warning')}</div>`).join('')||'<div class="empty">No medication draft returned.</div>'}</div></div><div class="page-actions" style="margin-top:12px">${canReview?`<button type="button" class="btn btn-success" onclick="window.doctorDecision('${n.id}','Approved')">Approve</button><button type="button" class="btn btn-warning" onclick="window.doctorDecision('${n.id}','Modified')">Modify</button><button type="button" class="btn btn-danger" onclick="window.doctorDecision('${n.id}','Rejected')">Reject</button>`:`<span class="tag warning">View only · qualified doctor review required</span>`}</div></div>`).join('')||'<div class="empty">No pending AI review requests.</div>'}</div><div class="panel" style="margin-top:18px"><div class="panel-header"><h3>Finalized Prescriptions</h3></div>${tableWrap(['ID','Patient','Specialty','Doctor','Decision','Date','Actions'],existing)}</div>`;lucide.createIcons();}
  window.doctorDecision=(nid,decision)=>{if(!['Doctor','HOD','Medical Director'].includes(state.currentUser?.role)){alert('Only a qualified clinical reviewer can approve, modify or reject an AI prescription draft.');return;}const n=state.notifications.find(x=>x.id===nid&&x.type==='ai'&&x.status==='Pending Doctor Review');if(!n){alert('This AI review is no longer pending. Refreshing the review queue.');renderPrescriptions();return;}if(!['Approved','Modified','Rejected'].includes(decision))return;let note='';if(decision==='Modified'){note=promptText('Doctor modification note','Modified after clinical review');if(note===null)return;}if(decision==='Approved'||decision==='Modified'){const rx={id:makeId('RX'),patientId:n.patientId,patient:n.patientName,specialty:n.specialty,doctor:state.currentUser?.name||'Authorized Doctor',decision,status:'Finalized',draft:clone(n.result?.prescriptionDraft||[]),doctorNote:note||'Doctor approved AI-supported draft.',date:nowISO()};state.data.prescriptions.push(rx);persist('prescriptions');}n.status=decision;addAudit(`AI_PRESCRIPTION_${decision.toUpperCase()}`,n.patientId||n.id,{doctorId:state.currentUser?.doctorId||state.currentUser?.email||'unknown',patientId:n.patientId||null});updateNotificationCount();renderPrescriptions();};
  window.editPrescription=idv=>{const x=state.data.prescriptions.find(v=>v.id===idv);if(!x)return;const note=promptText('Doctor note',x.doctorNote||'');if(note===null)return;x.doctorNote=note;persist('prescriptions');addAudit('PRESCRIPTION_UPDATED',idv);renderPrescriptions();};
  window.deletePrescription=idv=>{if(!confirmDelete('prescription'))return;state.data.prescriptions=state.data.prescriptions.filter(x=>x.id!==idv);persist('prescriptions');addAudit('PRESCRIPTION_DELETED',idv);renderPrescriptions();};

  function renderLaboratory(){const rows=state.data.labs.map(x=>`<tr><td>${x.id}</td><td>${esc(x.patient)}</td><td>${esc(x.test)}</td><td>${esc(x.result)}</td><td>${tag(x.status,x.status==='Abnormal'?'warning':'success')}</td><td>${x.date}</td><td>${actionBtns(`editLab('${x.id}')`,`deleteLab('${x.id}')`)}</td></tr>`).join('');document.getElementById('view-laboratory').innerHTML=pageHead('Laboratory Management','Tests, results and clinical review workflow',`<button class="btn btn-primary" onclick="addLab()">Add Lab Result</button>`)+tableWrap(['ID','Patient','Test','Result','Status','Date','Actions'],rows);lucide.createIcons();}
  window.addLab=()=>{const p=state.data.patients[0];const patientId=promptText('Patient ID',p?.id||'');if(!patientId||!patientById(patientId))return;const test=promptText('Test name','CBC');if(!test)return;const result=promptText('Result','Normal');if(result===null)return;const status=promptText('Status Normal/Abnormal/Pending','Pending');if(status===null)return;const x={id:makeId('LAB'),patientId,patient:patientById(patientId).name,test,result,status,date:today()};state.data.labs.push(x);persist('labs');addAudit('LAB_CREATED',x.id);renderLaboratory();};
  window.editLab=idv=>{const x=state.data.labs.find(v=>v.id===idv);if(!x)return;const test=promptText('Test',x.test);if(test===null)return;const result=promptText('Result',x.result);if(result===null)return;const status=promptText('Status',x.status);if(status===null)return;Object.assign(x,{test,result,status});persist('labs');addAudit('LAB_UPDATED',idv);renderLaboratory();};
  window.deleteLab=idv=>{if(!confirmDelete('lab result'))return;state.data.labs=state.data.labs.filter(x=>x.id!==idv);persist('labs');addAudit('LAB_DELETED',idv);renderLaboratory();};

  function renderPharmacy(){const rows=state.data.pharmacy.map(x=>`<tr><td>${x.id}</td><td>${esc(x.name)}</td><td>${x.stock}</td><td>${esc(x.unit)}</td><td>${x.expiry}</td><td>${tag(x.stock<20?'LOW':'Healthy',x.stock<20?'warning':'success')}</td><td>${actionBtns(`editMedicine('${x.id}')`,`deleteMedicine('${x.id}')`)}</td></tr>`).join('');document.getElementById('view-pharmacy').innerHTML=pageHead('Pharmacy Management','Inventory, expiry and prescription-linked dispensing',`<button class="btn btn-primary" onclick="addMedicine()">Add Medicine</button>`)+tableWrap(['ID','Medicine','Stock','Unit','Expiry','Status','Actions'],rows);lucide.createIcons();}
  window.addMedicine=()=>{const name=promptText('Medicine name');if(!name)return;const stock=Number(promptText('Opening stock','50'));if(!Number.isFinite(stock))return;const unit=promptText('Unit','tablets');if(unit===null)return;const expiry=promptText('Expiry YYYY-MM','2027-12');if(expiry===null)return;const x={id:makeId('MED'),name,stock,unit,expiry};state.data.pharmacy.push(x);persist('pharmacy');addAudit('MEDICINE_CREATED',x.id);renderPharmacy();};
  window.editMedicine=idv=>{const x=state.data.pharmacy.find(v=>v.id===idv);if(!x)return;const name=promptText('Medicine',x.name);if(name===null)return;const stock=Number(promptText('Stock',String(x.stock)));if(!Number.isFinite(stock))return;const expiry=promptText('Expiry',x.expiry);if(expiry===null)return;Object.assign(x,{name,stock,expiry});persist('pharmacy');addAudit('MEDICINE_UPDATED',idv);renderPharmacy();};
  window.deleteMedicine=idv=>{if(!confirmDelete('medicine'))return;state.data.pharmacy=state.data.pharmacy.filter(x=>x.id!==idv);persist('pharmacy');addAudit('MEDICINE_DELETED',idv);renderPharmacy();};

  function renderBilling(){const total=state.data.billing.reduce((s,x)=>s+num(x.amount),0);const rows=state.data.billing.map(x=>`<tr><td>${x.id}</td><td>${esc(x.patient)}</td><td>₹${num(x.amount).toLocaleString('en-IN')}</td><td>${tag(x.status,x.status==='Paid'?'success':'warning')}</td><td>${x.date}</td><td>${actionBtns(`editInvoice('${x.id}')`,`deleteInvoice('${x.id}')`)}</td></tr>`).join('');document.getElementById('view-billing').innerHTML=pageHead('Billing & Invoices','Consultation, lab, pharmacy and hospital service charges',`<button class="btn btn-primary" onclick="addInvoice()">Create Invoice</button>`)+`<div class="stats-grid">${kpi('Invoices',state.data.billing.length,'file-text')}${kpi('Paid',state.data.billing.filter(x=>x.status==='Paid').length,'check-circle','success')}${kpi('Revenue',`₹${total.toLocaleString('en-IN')}`,'indian-rupee','secondary')}</div>`+tableWrap(['Invoice','Patient','Amount','Status','Date','Actions'],rows);lucide.createIcons();}
  window.addInvoice=()=>{const pid=promptText('Patient ID',state.data.patients[0]?.id||'');if(!pid||!patientById(pid))return;const amount=Number(promptText('Amount','2500'));if(!Number.isFinite(amount))return;const status=promptText('Status Paid/Pending','Pending');if(status===null)return;const x={id:makeId('INV'),patientId:pid,patient:patientById(pid).name,amount,status,date:today()};state.data.billing.push(x);persist('billing');addAudit('INVOICE_CREATED',x.id);renderBilling();};
  window.editInvoice=idv=>{const x=state.data.billing.find(v=>v.id===idv);if(!x)return;const amount=Number(promptText('Amount',String(x.amount)));if(!Number.isFinite(amount))return;const status=promptText('Status',x.status);if(status===null)return;Object.assign(x,{amount,status});persist('billing');addAudit('INVOICE_UPDATED',idv);renderBilling();};
  window.deleteInvoice=idv=>{if(!confirmDelete('invoice'))return;state.data.billing=state.data.billing.filter(x=>x.id!==idv);persist('billing');addAudit('INVOICE_DELETED',idv);renderBilling();};

  function renderBeds(){const rows=state.data.beds.map(x=>`<tr><td>${x.id}</td><td>${esc(x.ward)}</td><td>${tag(x.status,x.status==='Available'?'success':'warning')}</td><td>${esc(x.patient||'-')}</td><td>${actionBtns(`editBed('${x.id}')`,`deleteBed('${x.id}')`)}</td></tr>`).join('');document.getElementById('view-beds').innerHTML=pageHead('Beds & Wards','Capacity, occupancy and allocation',`<button class="btn btn-primary" onclick="addBed()">Add Bed</button>`)+tableWrap(['Bed','Ward','Status','Patient','Actions'],rows);lucide.createIcons();}
  window.addBed=()=>{const ward=promptText('Ward','General');if(!ward)return;const status=promptText('Status Available/Occupied','Available');if(!status)return;const patient=status==='Occupied'?promptText('Patient name',''):'';const x={id:makeId('BED'),ward,status,patient:patient||''};state.data.beds.push(x);persist('beds');addAudit('BED_CREATED',x.id);renderBeds();};
  window.editBed=idv=>{const x=state.data.beds.find(v=>v.id===idv);if(!x)return;const ward=promptText('Ward',x.ward);if(ward===null)return;const status=promptText('Status',x.status);if(status===null)return;const patient=status==='Occupied'?promptText('Patient',x.patient):'';Object.assign(x,{ward,status,patient});persist('beds');addAudit('BED_UPDATED',idv);renderBeds();};
  window.deleteBed=idv=>{const x=state.data.beds.find(v=>v.id===idv);if(x?.status==='Occupied'){alert('Occupied bed cannot be deleted.');return;}if(!confirmDelete('bed'))return;state.data.beds=state.data.beds.filter(x=>x.id!==idv);persist('beds');addAudit('BED_DELETED',idv);renderBeds();};

  function renderOperations(){const rows=state.data.operations.map(x=>`<tr><td>${x.id}</td><td>${esc(x.patient)}</td><td>${esc(x.procedure)}</td><td>${esc(x.surgeon)}</td><td>${x.date}</td><td>${tag(x.status,x.status==='Scheduled'?'warning':'success')}</td><td>${actionBtns(`editOperation('${x.id}')`,`deleteOperation('${x.id}')`)}</td></tr>`).join('');document.getElementById('view-operations').innerHTML=pageHead('Operations / OT','Procedure scheduling and theatre workflow',`<button class="btn btn-primary" onclick="addOperation()">Add Procedure</button>`)+tableWrap(['ID','Patient','Procedure','Surgeon','Date','Status','Actions'],rows);lucide.createIcons();}
  window.addOperation=()=>{const pid=promptText('Patient ID',state.data.patients[0]?.id||'');if(!pid||!patientById(pid))return;const procedure=promptText('Procedure','Procedure');if(!procedure)return;const surgeon=promptText('Surgeon','Dr. ____');if(surgeon===null)return;const date=promptText('Date YYYY-MM-DD',today());if(date===null)return;const status=promptText('Status Scheduled/Completed/Cancelled','Scheduled');if(status===null)return;const p=patientById(pid);const x={id:makeId('OT'),patientId:pid,patient:p.name,procedure,surgeon,date,status};state.data.operations.push(x);persist('operations');addAudit('OT_CREATED',x.id);renderOperations();};
