  function renderCollege(){document.getElementById('view-college').innerHTML=pageHead('Medical College Administration','High-level academic and teaching administration',`<button class="btn btn-primary" onclick="navigate('medical-college')">Open College Operations</button>`)+`<div class="stats-grid">${kpi('Students',state.data.students.length,'graduation-cap','secondary')}${kpi('Faculty / Doctors',state.data.doctors.length,'users','primary')}${kpi('Departments',state.data.departments.length,'building-2','success')}${kpi('Research Projects',67,'flask-conical','warning')}</div><div class="cards-3"><div class="panel"><h3>Academic Administration</h3><p>Admissions, attendance, timetable, examinations and assessments.</p><button class="btn btn-outline" onclick="navigate('medical-college')">Manage</button></div><div class="panel"><h3>Clinical Education</h3><p>Clinical postings, anonymized cases, skills and logbooks.</p><button class="btn btn-outline" onclick="navigate('medical-college')">Manage</button></div><div class="panel"><h3>Research</h3><p>Student/faculty projects and publication tracking.</p><button class="btn btn-outline" onclick="navigate('reports')">Reports</button></div></div>`;lucide.createIcons();}

  function renderMedicalCollege(){const rows=state.data.students.map(s=>`<tr><td>${s.id}</td><td>${esc(s.name)}</td><td>${esc(s.year)}</td><td>${esc(s.dept)}</td><td>${tag(`${s.attendance}%`,s.attendance<75?'danger':'success')}</td><td>${esc(s.hostel)}</td><td>${actionBtns(`editStudent('${s.id}')`,`deleteStudent('${s.id}')`)}</td></tr>`).join('');document.getElementById('view-medical-college').innerHTML=pageHead('Medical College Operations','Students, clinical learning, attendance, logbook and research',`<button class="btn btn-primary" onclick="addStudent()">Add Student</button>`)+tableWrap(['ID','Student','Year','Department','Attendance','Hostel','Actions'],rows)+`<div class="cards-3" style="margin-top:18px"><div class="panel"><h3>AI Case Learning</h3><p>Anonymized or synthetic cases can be used for training and comparison with faculty review.</p><button class="btn btn-outline" onclick="startLearningCase()">Open Case</button></div><div class="panel"><h3>Attendance Exceptions</h3><p>${state.data.students.filter(s=>s.attendance<75).length} students below 75%.</p></div><div class="panel"><h3>Research</h3><p>Track projects, publications and supervisors.</p></div></div>`;lucide.createIcons();}
  window.addStudent=()=>{const name=promptText('Student name');if(!name)return;const year=promptText('Year','MBBS 1st Year');if(year===null)return;const dept=promptText('Department','Medicine');if(dept===null)return;const attendance=Number(promptText('Attendance %','90'));if(!Number.isFinite(attendance))return;const hostel=promptText('Hostel room','');if(hostel===null)return;const x={id:makeId('STU'),name,year,dept,attendance,hostel};state.data.students.push(x);persist('students');addAudit('STUDENT_CREATED',x.id);renderMedicalCollege();};
